// Node 6: Diff Engine — NEW vs RESOLVED vs PERSISTING
// Violation identity = a STABLE key (rule_id | selector | page_url), NOT the
// scan-prefixed id. This is what lets a violation that survives between scans be
// correctly detected as "persisting" instead of looking brand new every week.
// In production the previous keys come from PostgreSQL / the prior scan CSV.

const current = $('Crawl + Audit (Playwright + axe-core)').all().map(i => i.json);

const keyOf = v => `${v.rule_id}|${v.selector}|${v.page_url}`;

// Stable keys recorded in the previous scan (scan_20260516), loaded from storage.
const previousKeys = new Set([
  'link-name|.team-card:nth-child(2) a|https://example.com/about', // still present -> PERSISTING
  'aria-required-attr|.dashboard-widget|https://example.com/app',   // gone now    -> RESOLVED
  'duplicate-id|#main|https://example.com/'                          // gone now    -> RESOLVED
]);

const currentKeys = new Set(current.map(keyOf));

// Classify every current violation as NEW or PERSISTING
const classified = current.map(v => ({
  ...v,
  stable_key: keyOf(v),
  status: previousKeys.has(keyOf(v)) ? 'persisting' : 'new'
}));

// Anything in the previous scan that is no longer present has been RESOLVED
const resolved = [...previousKeys].filter(k => !currentKeys.has(k));

const newViolations        = classified.filter(v => v.status === 'new');
const persistingViolations = classified.filter(v => v.status === 'persisting');

// Severity-weighted compliance score (0-100). Critical issues hurt the most.
// score = 100 - (critical*8 + serious*3 + moderate*1 + minor*1 + persisting*1)
const sev = { critical: 8, serious: 3, moderate: 1, minor: 1 };
const newPenalty = newViolations.reduce((s, v) => s + (sev[v.impact] || 1), 0);
const persistingPenalty = persistingViolations.length * 1;
const currentScore = Math.max(0, 100 - newPenalty - persistingPenalty);
const previousScore = 70; // loaded from previous scan record
const scoreDelta = currentScore - previousScore;

console.log(`Diff complete: ${newViolations.length} new, ${persistingViolations.length} persisting, ${resolved.length} resolved | score ${currentScore} (${scoreDelta >= 0 ? '+' : ''}${scoreDelta})`);

return [{
  json: {
    scan_id: current[0]?.scan_id,
    domain: 'example.com',
    scan_date: current[0]?.collected_at,
    new: newViolations,
    persisting: persistingViolations,
    resolved: resolved,
    new_count: newViolations.length,
    persisting_count: persistingViolations.length,
    resolved_count: resolved.length,
    current_score: currentScore,
    previous_score: previousScore,
    score_delta: scoreDelta
  }
}];

// Node 7: Filter — only pass NEW violations to Claude API
// Persisting violations already have AI suggestions from a previous run

const diffResult = $('Diff Engine — New vs Resolved').first().json;
const newViolations = diffResult.new || [];

// Only process critical and serious new violations with Claude
// Minor/moderate get generic suggestions to save API cost
const forAI = newViolations.filter(v => ['critical','serious'].includes(v.impact));
const genericFix = newViolations.filter(v => ['moderate','minor'].includes(v.impact));

console.log(`Sending ${forAI.length} critical/serious violations to Claude API`);
console.log(`${genericFix.length} moderate/minor violations will get rule-based suggestions`);

return forAI.map(v => ({ json: { ...v, ai_tier: 'claude' } }));

