// Node 9: Parse Claude responses + merge with violation data + add rule-based suggestions

const claudeItems = $('Claude AI — Generate Fix Suggestions').all();
const filterItems = $('Filter — Critical/Serious for Claude').all();
const diffResult = $('Diff Engine — New vs Resolved').first().json;

// Parse Claude responses
const claudeSuggestions = claudeItems.map((item, i) => {
  const violation = filterItems[i]?.json || {};
  let aiSuggestion = null;

  try {
    const responseText = item.json?.content?.[0]?.text || '{}';
    // Strip any accidental markdown fences
    const clean = responseText.replace(/```json|```/g, '').trim();
    aiSuggestion = JSON.parse(clean);
  } catch (e) {
    aiSuggestion = {
      plain_english: `This ${violation.rule_id} violation needs attention.`,
      impact_statement: 'Affects screen reader and keyboard users.',
      code_fix: 'See WCAG ' + violation.wcag_criterion + ' for remediation guidance.',
      estimated_time: 'Unknown',
      risk_level: 'Low',
      parse_error: true
    };
  }

  return {
    json: {
      ...violation,
      ai_suggestion: aiSuggestion,
      ai_generated: true,
      processed_at: new Date().toISOString().split('T')[0]
    }
  };
});

// Add rule-based suggestions for moderate/minor violations
const allNew = diffResult.new || [];
const moderateMinor = allNew.filter(v => ['moderate','minor'].includes(v.impact));
const genericSuggestions = moderateMinor.map(v => ({
  json: {
    ...v,
    ai_suggestion: {
      plain_english: `A ${v.impact} ${v.rule_id} violation was detected.`,
      impact_statement: 'May affect assistive technology users.',
      code_fix: `Refer to axe-core rule ${v.rule_id} documentation.`,
      estimated_time: '5-15 minutes',
      risk_level: 'Low'
    },
    ai_generated: false,
    processed_at: new Date().toISOString().split('T')[0]
  }
}));

const allProcessed = [...claudeSuggestions, ...genericSuggestions];
console.log(`Processed ${claudeSuggestions.length} AI suggestions + ${genericSuggestions.length} rule-based suggestions`);

return allProcessed;

